-- Duel + live tournament additions (owner: Claude 2).
-- Runs AFTER supabase/schema.sql (Claude 1). Only adds indexes, functions and realtime publication;
-- does not change or rename existing tables.
-- ids are int (generated by default as identity), per Claude 1 in issue #1.
-- schema.sql already adds duels/tournaments/tournament_entries/notifications to realtime;
-- the block at the bottom is idempotent and additionally adds `locations`.

-- ---------- answers: allow "time ran out" ----------
-- In duels and live competitions a player can run out of time without choosing.
-- Such answers are stored with chosen_index = null and is_correct = false.
-- The existing check (chosen_index between 0 and 3) still applies to non-null values.
alter table answers alter column chosen_index drop not null;

-- ---------- Extra columns (additive only) ----------
-- Final scores, Elo change and bonus, so the result screen does not have to recompute them.
alter table duels add column if not exists result jsonb;
-- When the current live question was shown; the server measures answer time from this.
alter table tournaments add column if not exists question_started_at timestamptz;
alter table tournaments add column if not exists result jsonb;

-- ---------- Elo (atomic) ----------
-- Winner gains p_delta, loser loses p_delta. For a draw p_delta may be negative.
create or replace function update_elo(p_winner int, p_loser int, p_delta int)
returns void language sql as $$
  update users set elo = elo + p_delta where id = p_winner;
  update users set elo = elo - p_delta where id = p_loser;
$$;

-- ---------- Indexes ----------
create index if not exists duels_opponent_status_idx on duels (opponent_id, status);
create index if not exists duels_challenger_status_idx on duels (challenger_id, status);
create index if not exists locations_updated_idx on locations (updated_at);
-- tournament_entries already has primary key (tournament_id, user_id) in schema.sql.

-- ---------- Nearby users (Haversine, metres) ----------
-- Only users who turned sharing on and pushed a position in the last 2 minutes.
create or replace function nearby_users(p_user int, p_radius_m double precision default 50)
returns table (user_id int, name text, elo int, xp int, distance_m double precision)
language sql stable as $$
  with me as (
    select lat, lng from locations where user_id = p_user and sharing
  )
  select u.id, u.name, u.elo, u.xp, d.distance_m
  from locations l
  join users u on u.id = l.user_id
  cross join me
  cross join lateral (
    select 2 * 6371000 * asin(least(1, sqrt(
      power(sin(radians(l.lat - me.lat) / 2), 2) +
      cos(radians(me.lat)) * cos(radians(l.lat)) * power(sin(radians(l.lng - me.lng) / 2), 2)
    ))) as distance_m
  ) d
  where l.user_id <> p_user
    and l.sharing
    and l.updated_at > now() - interval '2 minutes'
    and d.distance_m <= p_radius_m
  order by d.distance_m;
$$;

-- ---------- Expire unanswered invitations (60 s) ----------
create or replace function expire_stale_invites()
returns int language sql as $$
  with x as (
    update duels set status = 'expired'
    where status = 'invited' and created_at < now() - interval '60 seconds'
    returning 1
  )
  select count(*)::int from x;
$$;

-- ---------- Realtime ----------
do $$
declare t text;
begin
  foreach t in array array['duels', 'tournaments', 'tournament_entries', 'locations'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;
